package app.move.kineto

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool

/**
 * Percussion workout cues bundled in res/raw (generated by scripts/make-cue-sounds.py):
 *
 * - tick:   maraca shake for the 5-second countdown
 * - rep:    castanet double click marking each repetition
 * - finish: cuica rising "whoop" + castanet roll at the end of an exercise
 * - rest:   two soft falling cuica "hoo"s when a rest break ends
 */
class CueSounds(context: Context) {
  private val pool = SoundPool.Builder()
    .setMaxStreams(4)
    .setAudioAttributes(
      AudioAttributes.Builder()
        .setUsage(AudioAttributes.USAGE_MEDIA)
        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
        .build(),
    )
    .build()

  private val ids = mapOf(
    "tick" to pool.load(context, R.raw.cue_tick, 1),
    "rep" to pool.load(context, R.raw.cue_rep, 1),
    "finish" to pool.load(context, R.raw.cue_finish, 1),
    "rest" to pool.load(context, R.raw.cue_rest, 1),
  )

  fun play(name: String, volume: Float = 1f) {
    ids[name]?.let { pool.play(it, volume, volume, 1, 0, 1f) }
  }

  fun stop() {
    pool.autoPause()
  }

  fun release() {
    pool.release()
  }
}
